from app import store


def get_customer(customer_id):
    return store.CUSTOMERS[customer_id]


def list_customers():
    return sorted(store.CUSTOMERS.values(), key=lambda c: c["id"])


def delete_customer(customer_id):
    """Delete a customer. Raises KeyError if missing, ValueError if invoices reference them."""
    if customer_id not in store.CUSTOMERS:
        raise KeyError(customer_id)
    if any(i["customer_id"] == customer_id for i in store.INVOICES):
        raise ValueError(f"customer {customer_id} has invoices and cannot be deleted")
    del store.CUSTOMERS[customer_id]

