from app import store


def get_customer(customer_id):
    return store.CUSTOMERS[customer_id]


def list_customers():
    return sorted(store.CUSTOMERS.values(), key=lambda c: c["id"])


def delete_customer(customer_id):
    """Close a customer. The row is never removed (ADR 60): invoices keep
    their customer_id for seven years and the ledger export joins on it."""
    customer = store.CUSTOMERS[customer_id]
    customer["closed_on"] = datetime.now(timezone.utc).date().isoformat()
    return customer

