from app import gateway


def pay(account_id, cents):
    try:
        receipt = gateway.charge(account_id, cents)
    except gateway.GatewayTimeout:
        # A timeout does not tell us whether the processor charged the card,
        # so do not retry here (that could double-charge). Report the outcome
        # as unknown and let the caller reconcile it.
        return {"status": "timeout", "receipt": None}
    return {"status": "paid", "receipt": receipt}

