from app import gateway, queue


def pay(account_id, cents):
    try:
        receipt = gateway.charge(account_id, cents)
    except gateway.GatewayTimeout:
        # ADR 0059: a timed-out charge may have gone through, so it is never
        # retried here. Hand it to the reconcile worker, which asks the
        # processor what happened before anything is charged again.
        queue.enqueue("reconcile", {"account_id": account_id, "cents": cents})
        return {"status": "pending"}
    return {"status": "paid", "receipt": receipt}

